from typing import Any

import polars as pl
import pytest

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "experimental" / "reflex-kernel"
sys.path.insert(0, str(APP_DIR))

from reflex_kernel import perf  # noqa: E402


@pytest.fixture(autouse=True)
def _no_samples() -> None:
    perf.clear()


def names() -> list[str]:
    return [name for _, name, _, _ in perf._samples]


def state(token: str = "abcdefgh-and-more") -> Any:  # noqa: S107  # a client token, not a secret
    return SimpleNamespace(router=SimpleNamespace(session=SimpleNamespace(client_token=token)))


def test_a_timed_handler_stays_the_kind_of_function_it_was() -> None:
    """Reflex runs plain, generator, async and async-generator handlers each its own way."""

    def plain(_self: Any, x: int) -> int:
        return x + 1

    def steps(_self: Any):
        yield 1
        yield 2

    async def waits(_self: Any) -> str:
        return "done"

    async def async_steps(_self: Any):
        yield "a"

    async def gather() -> list[str]:
        return [item async for item in perf.timed(async_steps)(state())]

    assert perf.timed(plain)(state(), x=1) == 2
    assert inspect.isgeneratorfunction(perf.timed(steps))
    assert list(perf.timed(steps)(state())) == [1, 2]
    assert inspect.iscoroutinefunction(perf.timed(waits))
    assert asyncio.run(perf.timed(waits)(state())) == "done"
    assert inspect.isasyncgenfunction(perf.timed(async_steps))
    assert asyncio.run(gather()) == ["a"]
    assert names() == ["plain", "steps", "waits", "async_steps"]
    # the wrapper keeps the handler's name and signature, which Reflex reads
    assert perf.timed(plain).__name__ == "plain"
    assert list(inspect.signature(perf.timed(plain)).parameters) == ["_self", "x"]


def test_a_handler_is_timed_even_when_it_raises_and_knows_its_session() -> None:
    def breaks(_self: Any) -> None:
        raise ValueError("no")

    with pytest.raises(ValueError, match="no"):
        perf.timed(breaks)(state("12345678rest"))
    assert [(name, session) for _, name, _, session in perf._samples] == [("breaks", "12345678")]


def test_the_one_view_handler_is_split_by_action() -> None:
    def view_event(_self: Any, **_payload: Any) -> None:
        return None

    perf.timed(view_event)(state(), slot="tab:r1", action="sort", arg=0)
    with perf.span("build view"):
        pass
    assert names() == ["view_event: sort", "step: build view"]


def test_texts_are_short() -> None:
    assert [perf.size_text(n) for n in (812, 14_000, 3_400_000, 1_400_000_000)] == [
        "812 B",
        "14 KB",
        "3.2 MB",
        "1.30 GB",
    ]
    assert [perf.ms_text(ms) for ms in (0.42, 12.4, 1800)] == ["0.4 ms", "12 ms", "1.8 s"]
    assert [perf.ago_text(s) for s in (12, 240, 11_520, 181_440)] == ["12 s", "4 min", "3.2 h", "2.1 d"]
    assert [perf.share_text(part, 200) for part in (0, 1, 100)] == ["", "<1%", "50%"]


def session(**namespace: Any) -> Any:
    db = SimpleNamespace(schema=lambda: {"char": {}}, sql=lambda _query: pl.DataFrame({"id": list(range(100))}))
    return SimpleNamespace(namespace={"pl": pl, "db": db, **namespace}, db=db, ai_history=[], ai_cost=0.0)


def test_the_report_says_what_is_big_what_was_slow_and_who_is_connected() -> None:
    mine = session(big=pl.DataFrame({"a": list(range(10_000))}), n=3, _hidden=1)
    perf.record("run_cell", 20, "minetoke")
    perf.record("run_cell", 900, "minetoke")
    perf.record("toggle_pane", 0.2, "othertok")
    records = [
        {"kind": "graphql", "source": "startgg", "op": "PlayerSets", "ms": 400},
        {"kind": "graphql", "source": "startgg", "op": "PlayerSets", "ms": 600, "error": "HTTP 429"},
        {"kind": "agent", "source": "smash-agent", "ms": 3000},
        {"kind": "note", "source": "x"},  # no time: not a call
    ]
    sizes = {"view": 300_000, "cells": 100_000, "busy": 5}
    view = perf.report(mine, "minetoken", {"minetoken": mine, "othertoken": session()}, records, sizes, ("pl", "db"))

    assert [row["name"] for row in view.variables] == ["big", "n"]  # biggest first; no pl, db or _hidden
    assert view.variables[0]["shape"] == "10,000 × 1"  # noqa: RUF001  # the app's own sign for a shape
    assert [row["what"] for row in view.memory][-1] == "everything else"
    assert {row["what"] for row in view.memory} >= {"this session's variables", "other sessions", "debug log"}
    assert [(row["id"], row["mine"]) for row in view.sessions] == [("minetoke", "1"), ("othertok", "")]

    handlers = {row["name"]: row for row in view.handlers}
    assert view.handlers[0]["name"] == "run_cell"  # by total time
    assert handlers["run_cell"]["runs"] == "2"
    assert handlers["run_cell"]["max"] == "900 ms"
    assert handlers["run_cell"]["slow"] == "1"
    assert handlers["toggle_pane"]["slow"] == ""
    assert view.slowest[0]["name"] == "run_cell"
    assert view.slowest[0]["took"] == "900 ms"

    calls = {row["what"]: row for row in view.calls}
    assert list(calls) == ["agent · smash-agent", "graphql · startgg · PlayerSets"]
    assert calls["graphql · startgg · PlayerSets"] | {"slow": ""} == {
        "what": "graphql · startgg · PlayerSets",
        "runs": "2",
        "median": "500 ms",
        "max": "600 ms",
        "total": "1.0 s",
        "errors": "1",
        "slow": "",
    }
    assert [row["name"] for row in view.state] == ["view", "cells"]  # flags and short texts are left out
    assert view.state[0]["share"] == "75%"
    assert next(tile for tile in view.tiles if tile["label"] == "Slow handlers")["value"] == "1"
    assert "## Handlers and steps" in view.text
    assert "run_cell | 2 |" in view.text
